const throttle = (fn, delay) => {
  let canRun = true;

  return function (...args) {
    // Ignore the call if we're still inside the cooldown period
    if (!canRun) return;

    fn(...args);

    canRun = false;

    setTimeout(() => {
      canRun = true; // Allow calls again once the delay is over
    }, delay);
  };
};

const click = () => {
  console.log("Button Clicked");
};

const throttleClick = throttle(click, 1000);

throttleClick(); // "Button Clicked"
throttleClick(); // ignored
throttleClick(); // ignored
throttleClick(); // ignored
